//   - error:              查询或校验失败时的错误。
func ListAgentModelCallLog(ctx context.Context, db DBTX, params ListAgentModelCallLogParams, opts ...dynq.QueryOption) (dynq.Result[AgentModelCallLog], error) {
	cfg, err := dynq.NewQueryConfig(agent_model_call_logRegistry, opts...)
	if err != nil {
		return dynq.Result[AgentModelCallLog]{}, err
	}
	if err := validateAgentModelCallLogParams(params, cfg); err != nil {
		return dynq.Result[AgentModelCallLog]{}, err
	}
	limit, err := dynq.CheckPagination(agent_model_call_logRegistry, params.Limit, params.Offset, params.After)
	if err != nil {
		return dynq.Result[AgentModelCallLog]{}, err
	}
	// 解析有效排序:未指定排序时回落表级 @default_sort。
	seq, err := dynq.ResolveSort(agent_model_call_logRegistry, cfg, params.OrderBy)
	if err != nil {
		return dynq.Result[AgentModelCallLog]{}, err
	}
	fp := dynq.CursorFingerprint(agent_model_call_logRegistry.Resource, seq)
	// 计算 SELECT 列:投影列并集排序列(排序所需列始终参与查询)。
	cols := dynq.SelectColumns(agent_model_call_logRegistry, params.SelectFields, seq)
	b := sq.Select(cols...).From("agent_model_call_log").PlaceholderFormat(sq.Dollar).Where(sq.And(buildAgentModelCallLogWhere(params))).
		OrderBy(dynq.OrderBySQL(seq)).Limit(uint64(limit) + 1)
	// After 非 nil 时为游标模式:解码并校验游标,从该位置继续读取。
	if params.After != nil {
		vals, err := dynq.DecodeCursor(*params.After, fp, seq)
		if err != nil {
			return dynq.Result[AgentModelCallLog]{}, err
		}
		seek, err := dynq.SeekPredicate(seq, vals)
		if err != nil {
			return dynq.Result[AgentModelCallLog]{}, err
		}
		b = b.Where(seek)
	}
	if params.Offset > 0 {
		b = b.Offset(uint64(params.Offset))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return dynq.Result[AgentModelCallLog]{}, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return dynq.Result[AgentModelCallLog]{}, err
	}
	items, err := pgx.CollectRows(rows, pgx.RowToStructByNameLax[AgentModelCallLog])
	if err != nil {
		return dynq.Result[AgentModelCallLog]{}, err
	}
	// 以 LIMIT n+1 探测是否还有下一页,并构造 nextCursor。
	hasMore := len(items) > int(limit)
	if hasMore {
		items = items[:limit]
	}
	var next string
	if hasMore {
		next, err = dynq.EncodeCursor(fp, seq, agent_model_call_logCursorValues(items[len(items)-1], seq))
		if err != nil {
			return dynq.Result[AgentModelCallLog]{}, err
		}
	}
	return dynq.Result[AgentModelCallLog]{Items: items, HasMore: hasMore, NextCursor: next}, nil
}

